     DATE_SUB('2014-01-10', INTERVAL '01 05:05' DAY_MINUTE),
     DATE_SUB('2014-01-10', INTERVAL '01 05' DAY_HOUR),
     DATE_SUB('2014-01-10', INTERVAL '1-01' YEAR_MONTH)
     \G
