     CONCAT('test','obclient', '1.0'),
     CONCAT('test','obclient', NULL)
     \G
*************************** 1. row ***************************
CONCAT('test','obclient', '1.0'): testobclient1.0
 CONCAT('test','obclient', NULL): NULL;

-- [F01-M0117] QUOTE
-- Mode: MySQL
-- Category: SQL function reference
-- Official source: https://github.com/oceanbase/oceanbase-doc/blob/017c8d35a015afa04ce1e1ce4b95675e3223c878/en-US/700.reference/500.sql-reference/100.sql-syntax/200.common-tenant-of-mysql-mode/400.functions-of-mysql-mode/200.single-row-functions-of-mysql-mode/200.string-functions-of-mysql-mode/7000.quote-of-mysql-mode.md
